#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-10-08

# Test: the git commit isolation lint can fail (#4664, PR #4668 review)
#
# Arms, each a throwaway tests dir passed to the lint:
#   quoted:  a message that names a commit is not a commit, so a dir with only
#            that line has nothing to check and the lint reports the scan broken
#   self:    a copy of the lint is not a committing test (same verdict)
#   comment: a commit whose only "isolation" is in comments FAILS
#   hash:    a # inside quotes is not a comment, so the commit after it on
#            the same line is still seen and FAILS
#   order:   a git_isolate call after the commit does not cover it, FAILS
#   real:    a commit after a real git_isolate call passes
# #4674, the six shapes the first lint did not see (each FAILS on cb1f6dc8,
# and each has a covered twin that must pass):
#   cont:    a commit on a continuation line (git ... \ then commit)
#   wrapper: a commit through a function whose body runs git
#   if:      a commit in an if, while, until or ! condition
#   merge:   a merge that makes a commit (not --ff-only, --squash or --abort)
#   tag:     a signed or annotated tag (tag -s, tag -a, tag -u)
#   repo:    git -C a config commit.gpgsign false covers repo a, not repo b
# and two shapes found in this repo's own tests while fixing #4674:
#   quoted-opt: a -c value with spaces (-c user.name='A B') before commit
#   exec:       git run by a function whose body runs "$@" (git_env git ...)
#
# Usage: test-git-commit-isolation-arms.sh [lint-path]   (default: the repo lint)

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LINT="${1:-$SCRIPT_DIR/test-git-commit-isolation.sh}"
WORK="$(mktemp -d "${TMPDIR:-/tmp}/ork-commit-iso-arms.XXXXXX")"
trap 'rm -rf "$WORK"' EXIT

# Built by concatenation so this file holds no signing command of its own.
c=commit
m=merge
t=tag
FAILED=0

# expect <arm> <want-rc> <want-text> <dir>
expect() {
  local out rc=0
  out="$(bash "$LINT" "$4" 2>&1)" || rc=$?
  if [[ "$rc" -ne "$2" ]] || [[ "$out" != *"$3"* ]]; then
    echo "FAIL [$1]: want rc=$2 with '$3', got rc=$rc: $out"
    FAILED=1
  else
    echo "PASS [$1]"
  fi
}

mkdir -p "$WORK/quoted"
printf '#!/usr/bin/env bash\necho "FAIL: x runs git %s without commit.gpgsign"\n' "$c" > "$WORK/quoted/t.sh"
expect quoted 1 "scan is broken" "$WORK/quoted"

mkdir -p "$WORK/self"
cp "$LINT" "$WORK/self/test-git-commit-isolation.sh"
expect self 1 "scan is broken" "$WORK/self"

mkdir -p "$WORK/comment"
printf '#!/usr/bin/env bash\n# call git_isolate here, or set commit.gpgsign=false\ngit init -q r\ngit -C r %s -qm x --allow-empty\n' "$c" > "$WORK/comment/t.sh"
expect comment 1 "FAIL: t.sh" "$WORK/comment"

# hash and order each sit next to an isolated file, so the scan has work to
# do and the arm reads the per-file verdict, not the "scan is broken" guard.
ok_file() {
  printf '#!/usr/bin/env bash\ngit_isolate iso\ngit init -q r && git -C r %s -qm x --allow-empty\n' "$c" > "$1/ok.sh"
}

mkdir -p "$WORK/hash"
ok_file "$WORK/hash"
printf '#!/usr/bin/env bash\ngit init -q r\necho "log #1"; git -C r %s -qm x --allow-empty\n' "$c" > "$WORK/hash/t.sh"
expect hash 1 "FAIL: t.sh" "$WORK/hash"

mkdir -p "$WORK/order"
ok_file "$WORK/order"
printf '#!/usr/bin/env bash\ngit init -q r\ngit -C r %s -qm x --allow-empty\ngit_isolate iso\n' "$c" > "$WORK/order/t.sh"
expect order 1 "FAIL: t.sh" "$WORK/order"

mkdir -p "$WORK/real"
printf '#!/usr/bin/env bash\nsource fixtures/git-isolate.sh\ngit_isolate iso\ngit init -q r && git -C r %s -qm x --allow-empty\n' "$c" > "$WORK/real/t.sh"
expect real 0 "OK: 1 committing" "$WORK/real"

# shape <arm> <bad-body> <good-body>: the bad file alone (beside ok.sh) FAILS,
# the good twin beside ok.sh passes with 2 committing files counted.
shape() {
  mkdir -p "$WORK/$1-bad" "$WORK/$1-good"
  ok_file "$WORK/$1-bad"
  ok_file "$WORK/$1-good"
  printf '#!/usr/bin/env bash\ngit init -q r\n%s\n' "$2" > "$WORK/$1-bad/t.sh"
  printf '#!/usr/bin/env bash\ngit init -q r\n%s\n' "$3" > "$WORK/$1-good/t.sh"
  expect "$1" 1 "FAIL: t.sh" "$WORK/$1-bad"
  expect "$1-covered" 0 "OK: 2 committing" "$WORK/$1-good"
}

shape cont \
  "git -C r -c user.name=t \\
    $c -qm x --allow-empty" \
  "git -C r -c user.name=t -c commit.gpgsign=false \\
    $c -qm x --allow-empty"
shape wrapper \
  "g() { git -C r \"\$@\"; }
g $c -qm x --allow-empty" \
  "g() { git -C r -c commit.gpgsign=false \"\$@\"; }
g $c -qm x --allow-empty"
shape wrapper-multiline \
  "gf() {
  git -C r \"\$@\"
}
gf $c -qm x --allow-empty" \
  "gf() {
  git -C r -c commit.gpgsign=false \"\$@\"
}
gf $c -qm x --allow-empty"
shape if \
  "if git -C r $c -qm x --allow-empty; then :; fi" \
  "if git -C r -c commit.gpgsign=false $c -qm x --allow-empty; then :; fi"
shape bang \
  "! git -C r $c -qm x" \
  "! git -C r -c commit.gpgsign=false $c -qm x"
shape merge \
  "git -C r $m --no-ff -m m feat" \
  "git -C r -c commit.gpgsign=false $m --no-ff -m m feat"
shape tag \
  "git -C r $t -s v1 -m v1" \
  "git -C r -c tag.gpgsign=false $t -a v1 -m v1"
shape repo \
  "git -C a config commit.gpgsign false
git -C b $c -qm x --allow-empty" \
  "git -C b config commit.gpgsign false
git -C b $c -qm x --allow-empty"

shape quoted-opt \
  "git -C r -c user.name='A B' $c -qm x --allow-empty" \
  "git -C r -c user.name='A B' -c commit.gpgsign=false $c -qm x --allow-empty"
shape exec \
  "ge() { env -u GIT_DIR \"\$@\"; }
ge git -C r $c -qm x --allow-empty" \
  "ge() { env -u GIT_DIR \"\$@\"; }
ge git -C r -c commit.gpgsign=false $c -qm x --allow-empty"

# A merge that makes no commit, and a lightweight tag, are not signing
# operations: a dir with only those has nothing to check.
mkdir -p "$WORK/nosign"
printf '#!/usr/bin/env bash\ngit -C r %s --ff-only feat\ngit -C r %s --abort\ngit -C r %s v1\n' "$m" "$m" "$t" > "$WORK/nosign/t.sh"
expect nosign 1 "scan is broken" "$WORK/nosign"

exit "$FAILED"
